inline const SampleRecord* SampleLink::firstRecord() const {
    if (first_record_) {
        return first_record_.get();
    }
    if (!is_loaded("first_record")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<SampleRecord>(ENTITY_NAME, id(), "first_record");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<SampleRecord>(firstRecordId());
}

inline const SampleRecord* SampleLink::secondRecord() const {
    if (second_record_) {
        return second_record_.get();
    }
    if (!is_loaded("second_record")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<SampleRecord>(ENTITY_NAME, id(), "second_record");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<SampleRecord>(secondRecordId());
}

inline eval::EvalResult<EntityBorrow<SampleRecord>> SampleLink::evalFirstRecord() const {
    return GeneratedRelationAccess::object(memory_resource(), "first_record", firstRecord(), false);
}

inline eval::EvalResult<EntityBorrow<SampleRecord>> SampleLink::evalSecondRecord() const {
    return GeneratedRelationAccess::object(
        memory_resource(), "second_record", secondRecord(), false);
}

inline std::optional<Json> SampleLink::borrowed_json(Memory r,
                                                     EntityJsonTraversal& traversal) const {
    GeneratedEntityJson projection(r, traversal, ENTITY_NAME, this, root, id_for_runtime());
    projection.field(
        "id",
        [&] {
            return generated_detail::encode(r, id_);
        },
        load_state.is_loaded("id"),
        true);
    projection.field(
        "first_record_id",
        [&] {
            return generated_detail::encode(r, first_record_id_);
        },
        load_state.is_loaded("first_record_id"),
        false);
    projection.field(
        "second_record_id",
        [&] {
            return generated_detail::encode(r, second_record_id_);
        },
        load_state.is_loaded("second_record_id"),
        false);
    projection.field(
        "name",
        [&] {
            return generated_detail::encode(r, name_);
        },
        load_state.is_loaded("name"),
        false);
    projection.field(
        "version",
        [&] {
            return generated_detail::encode(r, version_);
        },
        load_state.is_loaded("version"),
        true);
    projection.dynamic(dynamic);
    projection.forward<SampleRecord>("first_record",
                                     first_record_ ? &*first_record_ : nullptr,
                                     load_state.is_loaded("first_record"),
                                     generated_detail::encode(r, first_record_id_));
    projection.forward<SampleRecord>("second_record",
                                     second_record_ ? &*second_record_ : nullptr,
                                     load_state.is_loaded("second_record"),
                                     generated_detail::encode(r, second_record_id_));
    return projection.finish(dynamic_field_values());
}

inline void SampleLink::attachRuntimeStateRecursive(const EntityRuntimeState& target) {
    root.attach_runtime_state(target);
    if (first_record_) {
        first_record_->attachRuntimeStateRecursive(target);
    }
    if (second_record_) {
        second_record_->attachRuntimeStateRecursive(target);
    }
}

inline SampleLink::SampleLink(std::allocator_arg_t, Allocator a)
    : Base(std::allocator_arg, a),
      id_(generated_detail::default_value<std::uint64_t>(a.resource())),
      first_record_id_(generated_detail::default_value<std::uint64_t>(a.resource())),
      second_record_id_(generated_detail::default_value<std::uint64_t>(a.resource())),
      name_(generated_detail::default_value<String>(a.resource())),
      version_(generated_detail::default_value<std::int64_t>(a.resource())),
      first_record_(nullptr, detail::ScopedDelete<SampleRecord>{a.resource()}),
      second_record_(nullptr, detail::ScopedDelete<SampleRecord>{a.resource()}) {}

inline SampleLink::SampleLink(std::allocator_arg_t, Allocator a, const SampleLink& other)
    : Base(std::allocator_arg, a, other), id_(detail::clone_in(a.resource(), other.id_)),
      first_record_id_(detail::clone_in(a.resource(), other.first_record_id_)),
      second_record_id_(detail::clone_in(a.resource(), other.second_record_id_)),
      name_(detail::clone_in(a.resource(), other.name_)),
      version_(detail::clone_in(a.resource(), other.version_)),
      first_record_(generated_detail::copy_box(a.resource(), other.first_record_)),
      second_record_(generated_detail::copy_box(a.resource(), other.second_record_)) {}

inline SampleLink::SampleLink(SampleLink&&) noexcept = default;
inline SampleLink::~SampleLink() = default;

inline EntityDescriptor SampleLink::entity_descriptor(Memory r) {
    EntityDescriptor d(std::allocator_arg, Allocator(r), ENTITY_NAME);
    d.table("sample_link_data");
    d.service("sqlite");
    {
        auto& property = d.property("id", DataType::U64, "id").id().not_null();
        (void)property;
    }
    {
        auto& property = d.property("name", DataType::Text, "name").not_null();
        property.with_max_length(100);
        (void)property;
    }
    {
        auto& property = d.property("version", DataType::I64, "version").version().not_null();
        (void)property;
    }
    {
        auto& property = d.property("first_record_id", DataType::U64, "first_record").not_null();
        (void)property;
    }
    {
        auto& property = d.property("second_record_id", DataType::U64, "second_record").not_null();
        (void)property;
    }
    {
        auto& relation = d.relation("first_record", "SampleRecord");
        relation.local_key = "first_record_id";
        relation.foreign_key = "id";
        relation.many = false;
    }
    {
        auto& relation = d.relation("second_record", "SampleRecord");
        relation.local_key = "second_record_id";
        relation.foreign_key = "id";
        relation.many = false;
    }
    d.mask_fields({});
    return d;
}

